import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"58、【兌】 兌下兌上","description":"周易口訣義 - 58、【兌】 兌下兌上","frontmatter":{"title":"58、【兌】 兌下兌上","description":"周易口訣義 - 58、【兌】 兌下兌上"},"headers":[],"relativePath":"classics/koujueyi/060.md","filePath":"classics/koujueyi/060.md"}'),r={name:"classics/koujueyi/060.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_58、【兌】-兌下兌上" tabindex="-1">58、【兌】 兌下兌上 <a class="header-anchor" href="#_58、【兌】-兌下兌上" aria-label="Permalink to “58、【兌】 兌下兌上”">​</a></h1><p>象曰：麗澤，兌。君子以朋友講習。</p><p>初九：和兌，吉。</p><p>象曰：「和兌」之「吉」，行未疑也。</p><p>九二：孚兌，吉，悔亡。</p><p>象曰：「孚兌」之「吉」，信志也。</p><p>六三：來兌，兇。</p><p>象曰：「來兌」之「兇」，位不當也。</p><p>九四：商兌未寧，介疾有喜。</p><p>象曰：「九四」之「喜」，有慶也。</p><p>九五：孚於剝，有厲。</p><p>象曰：「孚於剝」，位正當也。</p><p>上六：引兌。</p><p>象曰：「上六引兌」，未光也。</p><p>解讀</p><p>「兌亨，利貞」者，兌澤能潤悅萬物，故謂「兌悅」也。喻人君能以兌澤潤於萬人，惠流人悅，無所不通，故曰「兌亨」也。以悅相親，恐陷邪諂，其所利者在貞正，故曰「利貞」也。象曰「麗澤，兌」者，麗猶連也；兩澤相連，上下俱悅，故曰「麗澤，兌」也。「君子以朋友講習」者，先儒雲：「同處師門曰朋，共執一志曰友。」友猶黨也。必須友者，學記雲：「獨學無友，即孤陋寡聞。」謂朋友聚居，講解道義，修習文禮，相悅之盛，莫盛於此。故鄭眾雲：「樂耽於酒，則有沉酗之兇；志累於樂，則有傷性之患。所以君子樂之美者，莫過於尚詩、書，敦習道義，教之盛矣，樂在斯焉。」</p><p>「初九，和兌，吉」者，處悅之初，而無私應，與眾和悅，天下皆親，以斯而往，何所疑乎？所以獲「吉」也。</p><p>「九二，孚兌，吉，悔亡」者，以剛處中，是懷信實之人，悅而施信，則吉從之，故曰「孚兌，吉」；失位而處，所以有悔；志在忠信，所以「悔亡」也。</p><p>「六三來兌，兇」者，以陰居陽位，是來求悅；以不正之身，妄來求悅，是佞邪之道，所以致兇也。</p><p>「九四，商兌未寧，介□有喜」者，商謂商量裁製之謂；介，隔也。六三以諂佞之身而近至尊，妄求幹寵。夫佞邪之人，國之患害。今九四既是權臣，為君委任，固宜與君商量裁製，介隔邪佞之人，內掌樞機，以匡王室，經營倫理，未遑安寧，故曰「商兌未寧」也。介，疾是隔邪。與君除害，四方安靜，故有喜慶，故曰「介□有喜」也。</p><p>九五：「孚於剝，有厲」者，剝是小人道長之稱也。九五為悅之主，固宜中正自安，惟賢是任，而乃反親上六，暱狎小人，遂為小人所害，危厲，故曰「孚於剝，有厲」。書曰：「遠耆德，比頑童，是為亂風也。」</p><p>上六引兌者，六以陰最居悅後，是自靜退，不妄求進，必須他人牽引，乃從眾悅，故曰「引兌」也。</p>',22)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
